using System;using System.Collections;using System.Collections.Generic;using System.IO;using System.Linq;
using UnityEditor;using UnityEngine;using UnityEngine.InputSystem;using UnityEngine.InputSystem.LowLevel;using UnityEngine.UIElements;using Abyss.Story;
namespace IntegratedCampaign.EditorTools {
public static class CampaignVerification {
 static Keyboard testKeyboard;static Stack<IEnumerator> stack;static string report;static int errors;static string reportFile;
 public static void Begin(bool nativeOnly=false){if(!EditorApplication.isPlaying)throw new InvalidOperationException("Start the direct ship test first.");EditorApplication.isPaused=false;EditorWindow.GetWindow(typeof(EditorWindow).Assembly.GetType("UnityEditor.GameView")).Focus();testKeyboard=InputSystem.AddDevice<Keyboard>("ShipRestoreVerificationKeyboard");reportFile=nativeOnly?"native-smoke.txt":"verification.txt";report="Reference: 0cd6cdf89930a069c0691d662b53d836dba0233b\n";errors=0;CampaignDeliveryVerification.AssertRemovedMechanics();stack=new();stack.Push(nativeOnly?NativeSmoke():Run());Application.runInBackground=true;Application.logMessageReceived+=Log;EditorApplication.update+=Tick;}
 public static void BeginCampaignSmoke(){Begin(true);reportFile="campaign-smoke.txt";stack.Clear();stack.Push(CampaignSmoke());}
 static IEnumerator CampaignSmoke(){var flow=CampaignFlow.Instance;flow.ReturnMenu();yield return Loaded();flow.NewGame();yield return Loaded();var story=UnityEngine.Object.FindFirstObjectByType<UnderwaterDayStory>();story.secondChapter.firstChapterDepartureRequested.Invoke();yield return Loaded();yield return Talk(UnityEngine.Object.FindFirstObjectByType<ShipCampaignDirector>());yield return Loaded();story=UnityEngine.Object.FindFirstObjectByType<UnderwaterDayStory>();story.secondChapter.secondChapterCompleted.Invoke();yield return Loaded();yield return Talk(UnityEngine.Object.FindFirstObjectByType<ShipCampaignDirector>());yield return NativeSmoke(true);}
 static void Log(string s,string trace,LogType type){if(type==LogType.Error||type==LogType.Exception)errors++;}
 static void Tick(){EditorApplication.QueuePlayerLoopUpdate();if(!EditorApplication.isPlaying){Finish();return;}try{if(stack.Count==0){Finish();return;}var top=stack.Peek();if(!top.MoveNext()){stack.Pop();return;}if(top.Current is IEnumerator child)stack.Push(child);else if(top.Current is AsyncOperation operation)stack.Push(WaitOperation(operation));}catch(Exception e){report+="FAIL "+e+"\n";Save();Finish();}}
 static void Finish(){EditorApplication.update-=Tick;Application.logMessageReceived-=Log;if(testKeyboard!=null){InputSystem.RemoveDevice(testKeyboard);testKeyboard=null;}stack=null;Save();}
 static void Save()=>File.WriteAllText("Tools/ShipRestore/"+reportFile,report);
 static void Check(bool ok,string message){report+=(ok?"PASS ":"FAIL ")+message+"\n";Save();if(!ok)throw new Exception(message);}
 static IEnumerator WaitOperation(AsyncOperation operation){while(!operation.isDone)yield return null;}
 static IEnumerator Wait(double seconds){double until=EditorApplication.timeSinceStartup+seconds;while(EditorApplication.timeSinceStartup<until)yield return null;}
 static IEnumerator Loaded(){yield return Wait(1);while(CampaignFlow.Instance.Transitioning)yield return null;yield return Wait(.4);}
 static string Signature(){var s=UnityEngine.Object.FindFirstObjectByType<ShipController>();var u=UnityEngine.Object.FindFirstObjectByType<ShipUIManager>();var p=UnityEngine.Object.FindFirstObjectByType<EnemySpawner>();var h=s.GetComponent<PlayerHealth>();return $"{s.acceleration}|{s.maxSpeed}|{s.turnSpeed}|{s.maxEnergy}|{s.energyDrainRate}|{s.idleZoom}|{s.moveZoom}|{s.dashZoom}|{h.maxHealth}|{u.baseXP}|{u.xpGrowthMultiplier}|{p.initialSpawnCount}|{p.spawnInterval}|{p.spawnRadius}|{p.difficultyIncreaseTimer}|{p.extraEnemiesPerUpgrade}|"+string.Join(",",p.allEnemyPrefabs.Select(e=>e.name));}
 static IEnumerator Talk(ShipCampaignDirector d){double end=EditorApplication.timeSinceStartup+8;while(d&&d.Dialogue&&d.Dialogue.Active&&EditorApplication.timeSinceStartup<end){d.Dialogue.Advance();yield return null;}}
 static Enemy[] Enemies()=>UnityEngine.Object.FindObjectsByType<Enemy>(FindObjectsSortMode.None);
 static IEnumerator AwaitStop(ShipCampaignDirector d){double until=EditorApplication.timeSinceStartup+5;while(!d.ProductionStopped&&EditorApplication.timeSinceStartup<until)yield return null;Check(d.ProductionStopped,"time boundary stops native production");Check(d.RemainingEnemies>0&&!d.Completed,"surviving enemies prevent completion");}
 static void Kill(){foreach(var enemy in Enemies())enemy.TakeDamage(100000,Vector2.zero);}
 static IEnumerator NativeSmoke(bool campaign=false){if(!campaign){Time.timeScale=1;yield return UnityEngine.SceneManagement.SceneManager.LoadSceneAsync(CampaignFlow.ShipScene);yield return null;}yield return Wait(.4);var ship=UnityEngine.Object.FindFirstObjectByType<ShipController>();var ui=UnityEngine.Object.FindFirstObjectByType<ShipUIManager>();var spawner=UnityEngine.Object.FindFirstObjectByType<EnemySpawner>();Check(CampaignFlow.Instance.SessionStarted==campaign,campaign?"native ship reached through menu and underwater story":"direct native scene; integration passive");Check(ship.vcam&&ship.vcam.Target.TrackingTarget==ship.transform,"native camera tracks native ship");var before=ship.transform.position;float oldEnergy=ship.currentEnergy;InputSystem.QueueStateEvent(testKeyboard,new KeyboardState(Key.D));yield return Wait(.25);InputSystem.QueueStateEvent(testKeyboard,new KeyboardState());yield return Wait(.1);Check(ship.transform.position.x>before.x&&ship.currentEnergy<oldEnergy,"same native movement and consumption via actual controls ("+before+" -> "+ship.transform.position+", "+oldEnergy+" -> "+ship.currentEnergy+")");ship.GetComponent<PlayerHealth>().TakeDamage(5);yield return Wait(.1);Check(Mathf.Abs(ui.healthFill.fillAmount-ship.GetComponent<PlayerHealth>().CurrentHealth/ship.GetComponent<PlayerHealth>().MaxHealth)<.01f,"native HUD reacts to actual damage");var prefab=spawner.allEnemyPrefabs.First(p=>p&&p.GetComponent<Enemy>()&&p.GetComponent<Enemy>().lootPrefab);var lootPrefab=prefab.GetComponent<Enemy>().lootPrefab;ship.currentEnergy=40;if(ui.isLootingXP)ui.ToggleLootMode();UnityEngine.Object.Instantiate(lootPrefab,ship.transform.position,Quaternion.identity);yield return Wait(.3);Check(ship.currentEnergy>40&&ui.currentXP==0,"real orb gives energy through native magnet");ui.ToggleLootMode();float xp=ui.currentXP;UnityEngine.Object.Instantiate(lootPrefab,ship.transform.position,Quaternion.identity);yield return Wait(.3);Check(ui.currentXP>xp,"real orb gives native upgrade XP");Check(Mathf.Abs(ui.energyFill.fillAmount-ship.currentEnergy/ship.maxEnergy)<.02f&&Mathf.Abs(ui.xpFill.fillAmount-ui.currentXP/ui.nextLevelXP)<.02f,"native HUD energy and XP display real state");var target=UnityEngine.Object.Instantiate(prefab,ship.transform.position+Vector3.right*6,Quaternion.identity);target.GetComponent<Enemy>().player=ship.transform;var visual=target.GetComponent<EnemyFishVisual>();if(visual){visual.ship=ship.transform;visual.shipCollider=ship.GetComponent<Collider2D>();}bool fired=false;double end=EditorApplication.timeSinceStartup+1.5;while(EditorApplication.timeSinceStartup<end){if(UnityEngine.Object.FindObjectsByType<Bullet>(FindObjectsSortMode.None).Length>0)fired=true;yield return null;}Check(fired,"native automatic targeting creates real projectiles");Check(ui.healthText&&ui.energyText&&ui.xpText,"native HUD text references retained");Check(errors==0,"no runtime errors in native smoke checks");ScreenCapture.CaptureScreenshot(campaign?"Tools/ShipRestore/campaign-play.png":"Tools/ShipRestore/native-play.png");Save();}
 static IEnumerator Run(){yield return Wait(.4);var f=CampaignFlow.Instance;var ship=UnityEngine.Object.FindFirstObjectByType<ShipController>();var native=UnityEngine.Object.FindFirstObjectByType<ShipUIManager>();var spawner=UnityEngine.Object.FindFirstObjectByType<EnemySpawner>();string signature=Signature();Check(!f.SessionStarted,"direct ShipScene 1 has passive story integration");Check(Enemies().Length>=spawner.initialSpawnCount,"native initial enemies spawn");Check(native.levelUpDocument&&native.healthFill&&native.energyFill&&native.xpFill,"native HUD and UI Toolkit references present");
 var initial=ship.transform.position;float energy=ship.currentEnergy;InputSystem.QueueStateEvent(testKeyboard,new KeyboardState(Key.D));yield return Wait(.3);InputSystem.QueueStateEvent(testKeyboard,new KeyboardState());yield return Wait(.1);Check(ship.transform.position.x>initial.x&&ship.currentEnergy<energy,"native movement and energy consumption ("+initial+" -> "+ship.transform.position+", energy "+energy+" -> "+ship.currentEnergy+")");bool mode=native.isLootingXP;InputSystem.QueueStateEvent(testKeyboard,new KeyboardState(Key.Space));yield return Wait(.1);InputSystem.QueueStateEvent(testKeyboard,new KeyboardState());Check(native.isLootingXP!=mode,"native Space orb selection");native.AddXP(native.nextLevelXP);yield return Wait(.2);Check(Time.timeScale==0,"native UI Toolkit card selection pauses play");native.OnCardClicked(0);yield return Wait(.1);Check(Time.timeScale==1&&native.currentLevel==2,"native card applies and resumes");ship.GetComponent<PlayerHealth>().TakeDamage(100000);yield return Wait(.2);Check(ship.GetComponent<PlayerHealth>().IsDead&&Time.timeScale==0,"direct ship keeps native death behavior");
 f.NewGame();yield return Loaded();var story=UnityEngine.Object.FindFirstObjectByType<UnderwaterDayStory>();Check(story&&story.Stage==UnderwaterDayStage.Beginning,"New Game begins underwater");story.secondChapter.firstChapterDepartureRequested.Invoke();yield return Loaded();var d=UnityEngine.Object.FindFirstObjectByType<ShipCampaignDirector>();Check(!d.Running&&d.Dialogue.Active,"first interlude is dialogue only");yield return Talk(d);yield return Loaded();story=UnityEngine.Object.FindFirstObjectByType<UnderwaterDayStory>();Check(f.Phase==CampaignPhase.Announcement&&story.secondChapter.Started,"interlude returns to announcement");story.secondChapter.secondChapterCompleted.Invoke();yield return Loaded();d=UnityEngine.Object.FindFirstObjectByType<ShipCampaignDirector>();Check(Signature()==signature,"campaign entry preserves native gameplay tuning and enemy pool");d.smallFishSeconds=.8f;yield return Talk(d);yield return Wait(.1);Check(ship=UnityEngine.Object.FindFirstObjectByType<ShipController>(),"ship exists");Check(ship.enabled,"control restored after one-time story");ship.GetComponent<ShipWeapons>().enabled=false;double paused=d.ActiveSeconds;Time.timeScale=0;yield return Wait(.25);Check(Math.Abs(d.ActiveSeconds-paused)<.001,"manual pause does not advance boundary timer");Time.timeScale=1;native=UnityEngine.Object.FindFirstObjectByType<ShipUIManager>();paused=d.ActiveSeconds;native.AddXP(native.nextLevelXP);yield return Wait(.25);Check(Math.Abs(d.ActiveSeconds-paused)<.001,"native card selection does not advance timer");native.OnCardClicked(0);yield return AwaitStop(d);int count=Enemies().Length;foreach(var e in Enemies())e.enabled=false;spawner=UnityEngine.Object.FindFirstObjectByType<EnemySpawner>();yield return Wait(spawner.spawnInterval+.2);Check(Enemies().Length==count&&!d.Completed,"no new spawn after native interval; existing enemies retained");int completions=0;d.chapterCompleted.AddListener(()=>completions++);Kill();yield return Loaded();Check(completions==1&&f.Phase==CampaignPhase.SharkJourney,"clearing combatants completes once and opens third underwater chapter");story=UnityEngine.Object.FindFirstObjectByType<UnderwaterDayStory>();yield return Wait(1);Check(story.thirdChapter.Started,"third underwater chapter restored");story.thirdChapter.chapterCompleted.Invoke();yield return Loaded();d=UnityEngine.Object.FindFirstObjectByType<ShipCampaignDirector>();d.sharkSeconds=.3f;yield return Talk(d);ship=UnityEngine.Object.FindFirstObjectByType<ShipController>();ship.GetComponent<ShipWeapons>().enabled=false;ship.GetComponent<PlayerHealth>().TakeDamage(100000);yield return Loaded();yield return Wait(1);d=UnityEngine.Object.FindFirstObjectByType<ShipCampaignDirector>();Check(f.Phase==CampaignPhase.SharkBattle&&!d.ProductionStopped&&d.ActiveSeconds==0,"campaign death restarts same chapter with fresh timer");Check(Signature()==signature,"retry uses native starting tuning");d.sharkSeconds=.3f;yield return Talk(d);d.GetComponent<ShipWeapons>().enabled=false;yield return AwaitStop(d);Kill();yield return Loaded();Check(f.Phase==CampaignPhase.WhaleBattle,"shark cleanup enters whale chapter");d=UnityEngine.Object.FindFirstObjectByType<ShipCampaignDirector>();d.whaleSeconds=.3f;yield return Talk(d);d.GetComponent<ShipWeapons>().enabled=false;yield return AwaitStop(d);Kill();yield return Wait(.2);float hp=d.GetComponent<PlayerHealth>().CurrentHealth;d.GetComponent<PlayerHealth>().TakeDamage(10000);Check(d.GetComponent<PlayerHealth>().CurrentHealth==hp,"final-only damage protection");double deadline=EditorApplication.timeSinceStartup+15;while(!GameObject.Find("Ending choices")&&EditorApplication.timeSinceStartup<deadline){if(d.Dialogue.Active)d.Dialogue.Advance();yield return null;}Check(GameObject.Find("Ending choices")&&GameObject.Find("White ceasefire flag"),"real final completion reaches white flag and ending choices");ScreenCapture.CaptureScreenshot("Tools/ShipRestore/final.png");f.ReturnMenu();yield return Loaded();Check(UnityEngine.SceneManagement.SceneManager.GetActiveScene().name==CampaignFlow.MenuScene&&Time.timeScale==1,"menu returns with clean time scale");Check(errors==0,"no runtime errors in current verification");report+="Runtime limits shortened for verification only; enemies killed through native damage API. Not full human balance testing.\n";Save();}
}
}
